function writeResultSelectionCode(fileName)
    [file, message] = fopen(fileName, 'w', 'n', 'UTF-8');
    if file < 0
        error('ComsolExport:WriteCode', '%s', message);
    end
    closeFile = onCleanup(@() fclose(file));
    code = {
        'import java.io.InputStream;'
        'import java.io.OutputStream;'
        'import java.net.URI;'
        'import java.nio.file.FileSystem;'
        'import java.nio.file.FileSystems;'
        'import java.nio.file.Files;'
        'import java.nio.file.Path;'
        'import java.nio.file.Paths;'
        'import java.util.Collections;'
        'import javax.xml.parsers.DocumentBuilderFactory;'
        'import javax.xml.transform.TransformerFactory;'
        'import javax.xml.transform.dom.DOMSource;'
        'import javax.xml.transform.stream.StreamResult;'
        'import org.w3c.dom.Document;'
        'import org.w3c.dom.Element;'
        'import org.w3c.dom.Node;'
        'import org.w3c.dom.NodeList;'
        ''
        'public class RestoreResultSelections {'
        '  // COMSOL validates solution indices against computed solutions in the API.'
        '  // Write the authored selections into the exported, unsolved model.'
        '  public static void main(String[] args) throws Exception {'
        '    Path file = Paths.get(args[0]).toAbsolutePath();'
        '    String[][] selections = {'
        '      {"NumericalFeature", "intTotal0", "p:outersolnumindices", "T", "30", "value", "", "valueMatrix", "1|0"},'
        '      {"NumericalFeature", "intTotal0", "p:solnum", "T", "30", "valueMatrix", "1|1,''1''"},'
        '      {"NumericalFeature", "intTotal0", "p:solnumindices", "T", "30", "value", "1 4", "valueMatrix", "1|2,''1'',''4''"},'
        '      {"NumericalFeature", "intTotal0", "p:showlooplevelinput", "T", "30", "valueMatrix", "1|3,''on'',''on'',''off''"},'
        '      {"NumericalFeature", "intTotal0", "p:looplevelinput", "T", "30", "valueMatrix", "1|2,''manualindices'',''manual''"},'
        '      {"NumericalFeature", "intTotal0", "p:showlooplevel", "T", "30", "valueMatrix", "1|3,''off'',''on'',''off''"},'
        '      {"NumericalFeature", "intTotal0", "p:looplevel", "T", "30", "valueMatrix", "2|0|2,''1'',''2''"},'
        '      {"NumericalFeature", "intTotal0", "p:showlooplevelindices", "T", "30", "valueMatrix", "1|3,''on'',''off'',''off''"},'
        '      {"NumericalFeature", "intTotal0", "p:looplevelindices", "T", "30", "valueMatrix", "0", "ValueRows", "2,''1'',''''"},'
        '      {"NumericalFeature", "intTotal0", "p:hasouter", "T", "30", "value", "on"},'
        '      {"NumericalFeature", "intRow0", "p:outersolnumindices", "T", "30", "value", "", "valueMatrix", "1|0"},'
        '      {"NumericalFeature", "intRow0", "p:solnum", "T", "30", "valueMatrix", "1|1,''1''"},'
        '      {"NumericalFeature", "intRow0", "p:solnumindices", "T", "30", "value", "1 4", "valueMatrix", "1|2,''1'',''4''"},'
        '      {"NumericalFeature", "intRow0", "p:showlooplevelinput", "T", "30", "valueMatrix", "1|3,''on'',''on'',''off''"},'
        '      {"NumericalFeature", "intRow0", "p:looplevelinput", "T", "30", "valueMatrix", "1|2,''manualindices'',''manual''"},'
        '      {"NumericalFeature", "intRow0", "p:showlooplevel", "T", "30", "valueMatrix", "1|3,''off'',''on'',''off''"},'
        '      {"NumericalFeature", "intRow0", "p:looplevel", "T", "30", "valueMatrix", "2|0|2,''1'',''2''"},'
